        narration: `${transition} สาวๆ ทุกคนในรถบัสต่างเข้ามารุมล้อม ${pName} บางคนมอบผ้าห่ม บางคนมอบอาหารร้อนๆ และ ${sName} เดินเข้ามาสบตากับเขาพร้อมรอยยิ้มที่เปลี่ยนจากสาวซึนเดระเป็นหญิงสาวที่เปิดใจอย่างสมบูรณ์!`,
