        sfxBgm: '[BGM: ซาวด์ดนตรีปิดฉากความแค้น สะอาด บริสุทธิ์ และผ่อนคลาย] [SFX: เสียงประตูปิดสนิท ปัง!, เสียงระบบล็อกอัตโนมัติ ชึก!]',
        lighting: 'ความเงียบสงบกลับคืนสู่ห้องเซฟเฮาส์หรู ไฟแอมเบียนท์ไลท์สว่างนวลตาตัดกับความตายข้างนอก',
