        sfxBgm: '[BGM: ดนตรีมหากาพย์โลกาวินาศที่กว้างใหญ่ไพศาล (Epic Ocean Apocalypse)] [SFX: เสียงลมพัดผ่านผืนน้ำ, เสียงคลื่นกระทบยอดตึก]',
