        narration: `${transition} พระเอกยืนพิงกราบเรือยอชต์ ในมือถือไรเฟิลจู่โจมสะพายเฉียง ข้างเอวมีปืนพกคู่ และรอบตัวมีโดรนลาดตระเวนบินวนคุ้มกัน ผู้รอดชีวิตจากตึกอื่นที่เคยคิดจะบุกปล้น เมื่อเห็นอาวุธสงครามและแววตาเย็นชาของเขา ต่างพากันก้มหัวถอยหนี ไม่มีใครกล้าแม้แต่จะส่งเสียงดังหรือสบสายตากับเขาอีกต่อไป!`,
